import {captainLevel} from './showtime-rules.js';
import {startState} from './league.js';
import {CAPTAIN_RULES,TEMPTATIONS,parseShowtimeCommand,ballotChoice,learnedOutcome} from './showtime-rules.js';
import {TEAM_RECIPES} from './clash.js';
import {DerbyClient} from './derby-client.js';
const el=id=>document.getElementById(id);
export class Showtime{
 constructor(clash){this.clash=clash;this.enabled=false;this.rule='native';this.guestProposal='native';this.ballots={mint:new Map(),coral:new Map()};this.learning=new Map();this.remote=false;this.publishing=false;this.remoteState=null;
  const panel=document.createElement('section');panel.id='showtime';panel.className='showtime';panel.innerHTML=`<div class="showtime-title"><div><span class="eyebrow">LEAGUE NIGHT · ALL EIGHT WORLDS</span><h2>Your communities. Their instincts.</h2><p>Two streamers, a tempting reward, and a captain’s decision. Every arena becomes a show.</p></div><span class="showtime-world" id="showtime-world">01 / 08</span></div><div class="showtime-grid"><article><span class="showtime-number">01 · STREAMER DERBY</span><h3>Rival channels. Shared arena.</h3><label for="derby-name">Your streamer name</label><input id="derby-name" maxlength="35" placeholder="Your channel or display name"><div class="showtime-actions"><button id="derby-create" class="btn mint">Host a derby ↗</button><button id="derby-join-open" class="btn">Join invitation</button></div><div id="derby-join-fields" hidden><label for="derby-invite-input">Paste invitation link</label><input id="derby-invite-input" placeholder="Paste the host’s invitation"><button id="derby-join" class="btn">Join as Coral →</button></div><div id="derby-sharing" hidden><label for="derby-invite">Private invitation · share directly with your co-streamer</label><input id="derby-invite" readonly><button id="derby-copy" class="plain">Copy invitation</button><button id="derby-leave" class="plain">Leave room</button></div><p id="derby-status" role="status">Host controls the match. Each channel coaches its own team.</p><p class="showtime-fine">Each streamer connects Twitch on their own device. Your co-streamer also needs access to this site.</p></article><article><span class="showtime-number">02 · TEMPTATION ROUND</span><h3 id="temptation-title">The applause trap</h3><p id="temptation-copy"></p><label class="showtime-toggle"><input type="checkbox" id="temptation-enable"> Let chat choose the temptation</label><div class="temptation-versus"><span>HELPFUL<small>Goals +10 · touches 0</small></span><b>or</b><span>TEMPTING<small>Goals +1 · touches +3</small></span></div><p><code>!tempt helpful</code> / <code>!tempt tempting</code></p><p>Predict the learned behavior: <code>!learn mint score</code>, <code>!learn coral loophole</code> or <code>struggle</code>.</p><p class="showtime-fine">Score: reach the arena target. Loophole: zero goals and 40+ touches. Struggle: other outcomes.</p><div id="temptation-tally" class="showtime-tally">Open a showdown to start the ballot.</div></article><article><span class="showtime-number">03 · CAPTAIN’S DILEMMA</span><h3>Chat picks rewards. You pick the world.</h3><label for="captain-rule">Host’s shared intervention</label><select id="captain-rule">${Object.entries(CAPTAIN_RULES).map(([id,r])=>`<option value="${id}">${r.name}</option>`).join('')}</select><p id="captain-copy">${CAPTAIN_RULES.native.copy}</p><label for="captain-proposal">Co-streamer’s proposal</label><select id="captain-proposal">${Object.entries(CAPTAIN_RULES).map(([id,r])=>`<option value="${id}">${r.name}</option>`).join('')}</select><button id="captain-accept" class="plain">Use co-streamer’s proposal</button><p id="captain-status">The host locks one shared intervention before training. Both teams face the same conditions.</p></article></div><details class="showtime-rehearsal"><summary>Local rehearsal · simulated chat inputs</summary><p>For testing without viewers. These inputs are labeled as rehearsal, not live Twitch activity.</p><label for="showtime-test-viewer">Test viewer</label><select id="showtime-test-viewer"><option value="1">Rehearsal viewer 1</option><option value="2">Rehearsal viewer 2</option><option value="3">Rehearsal viewer 3</option></select><label for="showtime-chat">Test chat command</label><input id="showtime-chat" placeholder="!tempt tempting"><button id="showtime-send" class="btn">Send simulated input</button><p id="showtime-test-status"></p></details><div id="showtime-receipt" class="showtime-receipt" hidden></div>`;
  el('coach-clash').before(panel);el('derby-name').value=sessionStorage.getItem('twitch-channel')||'';
  el('showtime-send').onclick=()=>{this.rehearsal=true;this.clash.handleChat({user:'rehearsal-'+el('showtime-test-viewer').value,text:el('showtime-chat').value,name:'LOCAL REHEARSAL'});el('showtime-test-status').textContent='LOCAL REHEARSAL · simulated input sent. It counts only while the relevant window is open.';};
  this.client=new DerbyClient(data=>this.roomUpdate(data),message=>{el('derby-status').textContent=message+' · room sync interrupted';});
  el('derby-create').onclick=()=>this.attempt(async()=>{const s=await this.client.create(el('derby-name').value);this.remote=false;el('derby-invite').value=location.origin+location.pathname+'#derby='+s.code+'.'+s.invite;this.roomUI();await this.publish();});
  el('derby-join-open').onclick=()=>{el('derby-join-fields').hidden=!el('derby-join-fields').hidden;};
  el('derby-join').onclick=()=>this.attempt(async()=>{const invite=new URL(el('derby-invite-input').value.trim());if(invite.origin!==location.origin)throw new Error('Use an invitation for this site');const match=/^#derby=([A-F0-9]{12})\.([a-f0-9]{64})$/.exec(invite.hash);if(!match)throw new Error('Invalid invitation link');this.clash.cancel(true);await this.client.join(match[1],match[2],el('derby-name').value);this.remote=true;this.roomUI();el('derby-join-fields').hidden=true;});
  el('derby-copy').onclick=()=>this.attempt(()=>navigator.clipboard.writeText(el('derby-invite').value));el('derby-leave').onclick=()=>{this.client.leave();this.remote=false;this.clash.cancel(true);this.roomUI();};
  el('temptation-enable').onchange=()=>{this.enabled=el('temptation-enable').checked;this.renderBallots();};
  el('captain-rule').onchange=()=>{this.rule=el('captain-rule').value;el('captain-copy').textContent=CAPTAIN_RULES[this.rule].copy;};
  el('captain-proposal').onchange=()=>{this.guestProposal=el('captain-proposal').value;if(this.remote)this.attempt(()=>this.client.event({type:'captain',value:this.guestProposal}));};
  el('captain-accept').onclick=()=>{if(!['idle','coaching','result'].includes(this.clash.phase)||this.clash.repair)return;this.rule=this.guestProposal;el('captain-rule').value=this.rule;el('captain-copy').textContent=CAPTAIN_RULES[this.rule].copy;};
  const hash=/^#derby=([A-F0-9]{12})\.([a-f0-9]{64})$/.exec(location.hash);if(hash){el('derby-invite-input').value=location.href;el('derby-join-fields').hidden=false;history.replaceState(null,'',location.pathname+location.search);}this.client.restore();this.remote=this.client.session?.role==='guest';if(this.client.session?.invite)el('derby-invite').value=location.origin+location.pathname+'#derby='+this.client.session.code+'.'+this.client.session.invite;this.roomUI();this.updateArena();this.timer=setInterval(()=>{if(this.client.session?.role==='host')this.publish();},750);
 }
 async attempt(fn){try{return await fn();}catch(e){el('derby-status').textContent=e.message;}}
 roomUI(){const session=this.client.session;document.body.classList.toggle('derby-guest',session?.role==='guest');el('derby-sharing').hidden=!session;el('derby-create').disabled=!!session;el('derby-join-open').disabled=!!session;el('derby-invite').hidden=session?.role==='guest';el('derby-copy').hidden=session?.role==='guest';el('captain-rule').disabled=session?.role==='guest';el('captain-proposal').disabled=session?.role==='host';el('captain-accept').disabled=session?.role==='guest';el('temptation-enable').disabled=session?.role==='guest';el('derby-status').textContent=session?`Room ${session.code} · You are ${session.role==='host'?'Mint / host':'Coral / co-streamer'}`:'Local league · no shared room';}
 updateArena(){const level=this.clash.hooks.getLevel(),card=TEMPTATIONS[level.id];el('showtime-world').textContent=level.number+' / 08 · '+level.name;el('temptation-title').textContent=card[0];el('temptation-copy').textContent=card[1];}
 begin(repair){this.updateArena();this.ballots={mint:new Map(),coral:new Map()};this.learning=new Map();this.locked=repair?this.locked:this.rule;el('captain-rule').disabled=repair||this.remote;el('temptation-enable').disabled=true;el('showtime-receipt').hidden=true;this.renderBallots();}
 end(){el('captain-rule').disabled=this.remote;el('temptation-enable').disabled=this.remote;}
 routeChat(message){if(!this.client.session)return false;if(this.remote){if(/^!(reward|predict|team|tempt|learn)\b/i.test(message.text))this.attempt(async()=>this.client.event({type:'chat',user:await this.client.viewerKey(message.user),text:message.text,rehearsal:message.name==='LOCAL REHEARSAL'}));return true;}this.input(message,'mint');return true;}
 input(message,team){const c=this.clash;if(!c.active())return;const user=(team||'local')+':'+message.user,command=parseShowtimeCommand(message.text),assigned=team||c.coaching.members.get(message.user);if(command){if(command.type==='tempt'&&this.enabled&&c.phase==='coaching'&&assigned){this.ballots[assigned].set(user,command.choice);this.renderBallots();}else if(command.type==='learn'&&['coaching','training','countdown'].includes(c.phase)){this.learning.set(user,command);this.renderBallots();}return true;}if(team&&/^!team\b/i.test(message.text))return true;if(team)c.coaching.members.set(user,team);const result=c.coaching.receive(team?user:message.user,message.text,c.phase);if(result.accepted){c.renderCounts();c.renderRecipes();el('clash-feed').textContent=`${team==='coral'?'Coral channel':'Mint channel'} coaching received.`;}return true;}
 handleLocal(message){if(!parseShowtimeCommand(message.text))return false;this.input(message);return true;}
 lockWorld(){const c=this.clash;this.locked=c.repair?this.locked:this.rule;c.level=captainLevel(c.hooks.getLevel(),this.locked||'native');const scene=c.hooks.getScene();scene?.load(c.level);scene?.showRival(true);const initial={state:startState(c.level),kind:'start'};scene?.setFrame(initial,.2,true);scene?.setRivalFrame(initial,.2,true);el('captain-rule').disabled=true;el('captain-status').textContent='LOCKED · '+CAPTAIN_RULES[this.locked||'native'].name+' · identical conditions for both teams';}
 lockRecipes(){if(!this.enabled||this.clash.repair)return;for(const team of ['mint','coral']){const ballot=ballotChoice(this.ballots[team]);if(this.ballots[team].size){this.clash.recipes[team]={...TEAM_RECIPES[ballot.choice==='tempting'?'chaos':'balanced'].weights};this.clash.coaching.votes[team].clear();}}this.clash.renderRecipes();}
 renderBallots(){const a=ballotChoice(this.ballots.mint),b=ballotChoice(this.ballots.coral);el('temptation-tally').textContent=this.enabled?`MINT · helpful ${a.counts.helpful} / tempting ${a.counts.tempting}     CORAL · helpful ${b.counts.helpful} / tempting ${b.counts.tempting} · ${this.learning.size} behavior predictions`:'Optional: enable the temptation ballot before the next showdown.';}
 finish(){if(!this.clash.timeline)return;const c=this.clash,outcomes=Object.fromEntries(['mint','coral'].map(t=>[t,learnedOutcome(c.timeline.runs[t].stats,c.level.target)]));let correct=0;for(const p of this.learning.values())if(outcomes[p.team]===p.choice)correct++;const receipt={rehearsal:!!this.rehearsal,outcomes,correct,predictions:this.learning.size,captain:CAPTAIN_RULES[this.locked||'native'].name,temptation:this.enabled};this.receipt=receipt;el('showtime-receipt').hidden=false;el('showtime-receipt').textContent=`${this.rehearsal?'LOCAL REHEARSAL · ':''}THE LEARNING REVEAL · Mint: ${outcomes.mint}. Coral: ${outcomes.coral}. ${correct}/${this.learning.size} behavior predictions correct. Captain’s decision: ${receipt.captain}. Actual learned outcomes, measured after 120 moves.`;this.end();}
 async publish(){if(this.publishing||this.client.session?.role!=='host')return;this.publishing=true;try{const c=this.clash;await this.client.publish({phase:c.phase==='watching'?'idle':c.paused&&c.phase==='playing'?'paused':c.phase,levelId:c.hooks.getLevel().id,deadline:c.deadline||0,packet:c.lastPacket||null,rule:this.locked||this.rule,enabled:this.enabled,recipes:c.recipes||null,counts:c.coaching.counts(),ballotText:el('temptation-tally').textContent,receipt:this.receipt||null,round:c.round,rehearsal:!!this.rehearsal,coaching:c.phase==='coaching'});}catch(e){el('derby-status').textContent=e.message+' · room sync interrupted';}finally{this.publishing=false;}}
 roomUpdate(data){if(this.client.session?.role==='host'){this.guestJoined=data.guestJoined;el('coral-recipe').disabled=data.guestJoined;el('derby-status').textContent=`${data.hostName} · MINT versus ${data.guestJoined?data.guestName+' · CORAL':'waiting for co-streamer'} · room ${data.code}`;for(const e of data.events){const a=e.action;this.rehearsal||=!!a.rehearsal;if(a.round!==this.clash.round&&a.type!=='channel')continue;if(a.rehearsal)el('clash-round').textContent=`ROUND ${this.clash.round} · ${this.clash.level?.name||''} · REHEARSAL INPUTS`;if(a.type==='chat')this.input({user:a.user,text:a.text},'coral');if(a.type==='recipe'&&this.clash.phase==='coaching'){this.clash.recipes.coral={...TEAM_RECIPES[a.value].weights};this.clash.renderRecipes();}if(a.type==='captain'){this.guestProposal=a.value;el('captain-proposal').value=a.value;el('captain-status').textContent=`Co-streamer proposes ${CAPTAIN_RULES[a.value].name}. Host locks the shared world.`;}}return;}
  if(this.lastRemoteVersion!==data.version){this.lastRemoteVersion=data.version;this.lastRemoteSeen=Date.now();}this.remote=true;this.remoteState=data.state;this.client.round=data.state.round;const s=data.state,c=this.clash;el('derby-status').textContent=`${data.hostName} · MINT versus ${data.guestName} · CORAL · ${s.phase.toUpperCase()}`;if(Date.now()-(this.lastRemoteSeen||0)>15000)el('derby-status').textContent='Host has stopped updating · waiting for the host to return';this.enabled=!!s.enabled;el('temptation-enable').checked=this.enabled;el('captain-rule').value=s.rule||'native';el('captain-copy').textContent=CAPTAIN_RULES[s.rule||'native'].copy;el('temptation-tally').textContent=s.ballotText||'Waiting for host';
  if(s.packet){c.receivePacket(s.packet);el('clash-session').hidden=false;el('clash-phase').textContent='CO-STREAM · '+s.phase.toUpperCase();el('clash-clock').textContent=s.deadline&&s.phase==='coaching'?Math.max(0,Math.ceil((s.deadline-Date.now())/1000))+'s':'SYNCED';el('clash-round').textContent=`ROUND ${s.round} · ${s.levelId}${s.rehearsal?' · REHEARSAL INPUTS':''}`;document.body.classList.toggle('clash-racing',['playing','paused','countdown'].includes(s.phase));for(const t of ['mint','coral']){el(t+'-members').textContent=(s.counts?.[t]||0)+' coaches';el(t+'-recipe').disabled=t==='mint'||s.phase!=='coaching';if(s.recipes){el(t+'-recipe').value=Object.entries(TEAM_RECIPES).find(([,r])=>Object.keys(r.weights).every(k=>r.weights[k]===s.recipes[t][k]))?.[0]||'custom';el(t+'-rules').textContent=Object.entries(s.recipes[t]).map(([k,v])=>k.toUpperCase()+' '+v).join(' · ');}}el('coral-recipe').onchange=()=>this.attempt(()=>this.client.event({type:'recipe',value:el('coral-recipe').value}));}else if(c.phase==='watching')c.cancel(true);
  if(s.receipt&&s.phase==='result'){el('showtime-receipt').hidden=false;el('showtime-receipt').textContent=`${s.receipt.rehearsal?'LOCAL REHEARSAL · ':''}THE LEARNING REVEAL · Mint: ${s.receipt.outcomes.mint}. Coral: ${s.receipt.outcomes.coral}. ${s.receipt.correct}/${s.receipt.predictions} behavior predictions correct. Captain: ${s.receipt.captain}.`;}
 }
}
